<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';

function require_admin_page(): array {
  $u=current_user();
  if(!$u){header('Location: /admin/login.php');exit;}
  if($u['role']!=='admin'){http_response_code(403);exit('Administrator access required.');}
  return $u;
}

function admin_svg(string $name): string {
  $icons=[
    'grid'=>'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    'layers'=>'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',
    'orders'=>'<path d="M8 4h11v17H5V7z"/><path d="M8 3v4M16 3v4M5 10h14M8 14h8M8 17h5"/>',
    'users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    'payments'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>',
    'chart'=>'<path d="M3 3v18h18"/><path d="m7 14 4-4 4 3 6-7"/>',
    'globe'=>'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/>',
    'mail'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
    'logout'=>'<path d="M10 17l5-5-5-5M15 12H3"/><path d="M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/>',
    'menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>',
    'close'=>'<path d="m18 6-12 12M6 6l12 12"/>',
  ];
  $body=$icons[$name]??$icons['grid'];
  return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">'.$body.'</svg>';
}

function admin_header(string $active,string $title): void {
