  $safeName=htmlspecialchars((string)$user['name'],ENT_QUOTES,'UTF-8');
  $initial=strtoupper(substr((string)$user['name'],0,1));
  $links=[
    ['overview','/admin/?tab=overview','Overview','grid'],
    ['services','/admin/?tab=services','Service controllers','layers'],
    ['orders','/admin/?tab=orders','Orders','orders'],
    ['customers','/admin/?tab=customers','Customers','users'],
    ['payments','/admin/?tab=payments','Payments','payments'],
    ['fx','/admin/?tab=fx','Payment FX rates','chart'],
  ];
