idth:26px;height:26px;margin-right:8px;background:#f0f2ff;color:#5550c8;border-radius:7px}.service-table-icon svg{width:14px;height:14px}.status-row{display:grid;grid-template-columns:9px 1fr auto;align-items:center;gap:9px;padding:10px 0;border-bottom:1px solid #edf0f5}.status-row:last-child{border-bottom:0}.state-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#98a2b3;vertical-align:middle;margin-right:5px}.state-dot.on{background:#16835b}.state-dot.off{background:#a2aab8}.status-name{color:#586579;font-size:11px;text-transform:capitalize}.status-row strong{font-size:11px}.status-track{grid-column:1/-1;height:4px;margin-top:-3px;background:#eef0f4;border-radius:9px;overflow:hidden}.status-track i{display:block;height:100%;border-radius:9px}.chart{display:block;width:100%;height:210px;background:#fff;border:1px solid #edf0f5;border-radius:9px}.hidden{display:none!important}.sidebar-scrim{display:none}.section-label{margin:21px 0 9px;color:#788499;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.1em}@media(max-width:1100px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-lower{grid-template-columns:1fr}.page-wrap{padding-left:24px;padding-right:24px}.topbar{padding:0 24px}}@media(max-width:820px){.analytics-grid{grid-template-columns:1fr}.sidebar{transform:translateX(-101%);transition:transform .2s ease;box-shadow:12px 0 35px #10182820}.sidebar.open{transform:translateX(0)}.sidebar-scrim.visible{display:block;position:fixed;inset:0;background:#10182872;z-index:25}.main{margin-left:0}.menu-toggle{display:inline-flex}.topbar{justify-content:flex-start;padding:0 17px}.top-user{margin-left:auto}.page-wrap{padding:23px 17px 34px}.split{grid-template-columns:1fr}}@media(max-width:520px){.topbar{height:56px}.crumb{font-size:9px}.top-user>span:last-child{display:none}.page-heading{align-items:flex-start;flex-direction:column;margin-bottom:18px}.page-heading h1{font-size:21px}.stats{grid-template-columns:repeat(